import { defineEventHandler, getRequestURL, sendRedirect } from 'h3'
import { LEGACY_REDIRECTS } from '~/server/utils/legacyRedirects'

/**
 * Legacy Wix product URLs → the new product routes (301).
 *
 * The map is generated by `scripts/build-redirects.mjs` from the reviewed manifest; every
 * destination was verified to return 200 before generation. Matching is tried on the raw
 * pathname first (Wix paths carry percent-encoded characters such as `%C2%B7` and `%2C`),
 * then on the decoded form.
 */
export default defineEventHandler((event) => {
  const { pathname } = getRequestURL(event)
  if (!pathname || pathname === '/') return

  let target = LEGACY_REDIRECTS[pathname]
  if (!target) {
    try {
      target = LEGACY_REDIRECTS[decodeURIComponent(pathname)]
    }
    catch {
      // Malformed escapes: no match, fall through.
    }
  }
  if (!target) {
    try {
      target = LEGACY_REDIRECTS[encodeURI(pathname)]
    }
    catch {
      // Unencodable path: no match, fall through.
    }
  }

  if (target) return sendRedirect(event, target, 301)
})
